10	async function getTargets(port) {
11	    return new Promise((resolve, reject) => {
12	        http.get(`http://localhost:${port}/json`, (res) => {
13	            let data = '';
14	            res.on('data', chunk => data += chunk);
15	            res.on('end', () => {
16	                try { resolve(JSON.parse(data)); }
17	                catch(e) { reject(new Error(`Parse error: ${e.message}`)); }
18	            });
19	        }).on('error', e => reject(new Error(`Connection error: ${e.message}`)));
20	    });
21	}
