23	function sendCDP(ws, method, params = {}) {
24	    return new Promise((resolve, reject) => {
25	        const id = Math.floor(Math.random() * 100000);
26	        const msg = JSON.stringify({id, method, params});
27	        const handler = (data) => {
28	            try {
29	                const resp = JSON.parse(data.toString());
30	                if (resp.id === id) {
31	                    ws.removeListener('message', handler);
32	                    if (resp.error) reject(new Error(resp.error.message));
33	                    else resolve(resp.result);
34	                }
35	            } catch(e) {}
36	        };
37	        ws.on('message', handler);
38	        ws.send(msg);
39	        setTimeout(() => { ws.removeListener('message', handler); reject(new Error(`Timeout`)); }, 10000);
40	    });
41	}
