49	                    await sendCDP(ws, 'Network.enable');
50	                    const result = await sendCDP(ws, 'Network.getAllCookies');
51	                    ws.close();
52	                    resolve(result.cookies || []);
53	                } catch(e) {
54	                    ws.close();
55	                    reject(e);
